// Benchmark boilerplate generated by Benchmark

import Benchmark
import SolidPostScript
import SolidPostScriptPlutoVG
import SolidPostScriptRaster
import SolidRaster
import SolidRasterBenchmarkSupport

let benchmarks: @Sendable () -> Void = {
  let backend: RasterBenchmarkBackend
  let workloads: [RasterRendererBenchmarkWorkload]
  do {
    backend = try RasterBenchmarkBackend.current()
    workloads = try RasterRendererBenchmarkFixtures.all()
  } catch {
    fatalError("Unable to prepare raster comparison benchmarks: \(error)")
  }

  switch backend {
  case .native:
    register(workloads) { workload in
      RasterImageTarget(
        pixelWidth: workload.pixelWidth,
        pixelHeight: workload.pixelHeight,
        deviceDescriptor: workload.deviceDescriptor
      )
    }
    registerSeparations([workloads[0], workloads[4], workloads[6]])
  case .plutovg:
    register(workloads) { workload in
      PlutoVGImageTarget(
        pixelWidth: workload.pixelWidth,
        pixelHeight: workload.pixelHeight,
        deviceDescriptor: workload.deviceDescriptor
      )
    }
  }
}

private func registerSeparations(_ workloads: [RasterRendererBenchmarkWorkload]) {
  let configuration = Benchmark.Configuration(
    metrics: [.wallClock, .mallocCountTotal, .peakMemoryResidentDelta],
    warmupIterations: 3,
    scalingFactor: .one,
    maxDuration: .seconds(10),
    maxIterations: 100
  )
  for workload in workloads {
    Benchmark("CMYK Separation \(workload.name)", configuration: configuration) { benchmark in
      benchmark.startMeasurement()
      for _ in benchmark.scaledIterations {
        let output = try! RasterBenchmarkReplay.render(
          workload,
          to: RasterSeparationTarget(deviceDescriptor: workload.deviceDescriptor)
        )
        blackHole(output)
      }
    }
  }
}

private func register<Target: GraphicsTarget>(
  _ workloads: [RasterRendererBenchmarkWorkload],
  makeTarget: @escaping @Sendable (RasterRendererBenchmarkWorkload) -> Target
) where Target.PageOutput == RasterImage, Target.Output == [RasterImage] {
  for workload in workloads {
    let thresholds =
      workload.enforcesPerformanceGate
      ? BenchmarkThresholds(relative: [.p50: 100])
      : BenchmarkThresholds()
    let configuration = Benchmark.Configuration(
      metrics: [.wallClock],
      warmupIterations: 3,
      scalingFactor: .one,
      maxDuration: .seconds(10),
      maxIterations: 100,
      thresholds: [.wallClock: thresholds]
    )
    Benchmark(workload.name, configuration: configuration) { benchmark in
      benchmark.startMeasurement()
      for _ in benchmark.scaledIterations {
        let output = try! RasterBenchmarkReplay.render(workload, to: makeTarget(workload))
        blackHole(output)
      }
    }
  }
}
